// C++17/20: throw() is synonym for noexcept
void func_safe() noexcept;
void func_legacy() throw(); // Equivalent to noexcept

// Function Pointer Compatibility Rules
using Ptr_Throwing = void (*)();
using Ptr_NoExcept = void (*)() noexcept;

Ptr_Throwing ptr_a = func_safe; // OK (Relaxing specification allowed)
// Ptr_NoExcept ptr_b = func_throwing; // Error (Cannot tighten specification)

// Virtual Function Overrides
struct Base {
    virtual void check() noexcept = 0;
};

struct Derived : Base {
    // Override must maintain or strengthen the restriction
    void check() noexcept override; // OK
    // void check() override; // ERROR: incompatible exception spec
};
